// Upload image to Supabase Storage, return public URL
// Upload image via Edge Function proxy — bypasses iOS Safari CORS/Storage issues
// Downscale + recompress an image (base64 data URL) before upload. Phone photos are often
// 3-8MB; this caps the longest side at maxDim and re-encodes as JPEG, typically cutting size
// by 80-95%. Faster uploads on mobile data, smaller storage, snappier loads. Falls back to the
// original on any failure (e.g. canvas blocked) so upload still works.
function compressImage(base64DataUrl, maxDim = 1200, quality = 0.8) {
  return new Promise((resolve) => {
    try {
      const img = new Image();
      img.onload = () => {
        try {
          let { width, height } = img;
          if (width > maxDim || height > maxDim) {
            if (width >= height) { height = Math.round(height * (maxDim / width)); width = maxDim; }
            else { width = Math.round(width * (maxDim / height)); height = maxDim; }
          }
          const canvas = document.createElement("canvas");
          canvas.width = width; canvas.height = height;
          const ctx = canvas.getContext("2d");
          if (!ctx) { resolve(base64DataUrl); return; }
          ctx.drawImage(img, 0, 0, width, height);
          // JPEG drops transparency (fine for photos/avatars) and compresses well.
          const out = canvas.toDataURL("image/jpeg", quality);
          resolve(out && out.length > 20 ? out : base64DataUrl);
        } catch (err) { devWarn("compressImage: canvas/encode failed, using original", err); resolve(base64DataUrl); }
      };
      img.onerror = (err) => { devWarn("compressImage: image failed to load (CORS/format?), using original", err); resolve(base64DataUrl); };
      img.src = base64DataUrl;
    } catch (err) { devWarn("compressImage: unexpected failure, using original", err); resolve(base64DataUrl); }
  });
}

// Upload an image (base64 data URL) directly to Supabase Storage and return its public URL.
// Direct-to-Storage means NO Edge Function is required — just a public "images" bucket.
// Falls back to returning null on failure (callers keep the local preview / handle gracefully).
async function uploadImage(base64DataUrl, token, userId) {
  if (!base64DataUrl || !token) return null;
  try {
    // Compress/resize first (no-op fallback to original if it fails). Always JPEG after this.
    const compressed = await compressImage(base64DataUrl);
    const mime = compressed.match(/data:(.*?);/)?.[1] || "image/jpeg";
    const ext = mime.split("/")[1]?.split("+")[0] || "jpg";
    // base64 → binary blob
    const base64 = compressed.split(",")[1] || "";
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    // A File (not a bare Blob) so CapacitorHttp's native bridge treats the body as a binary
    // upload and base64-encodes it — a plain Blob falls through its type check and is sent as
    // broken JSON. A File is also a valid fetch body on web, so this works in both paths.
    const blob = new File([bytes], `upload.${ext}`, { type: mime });
    // Unique path per user so uploads don't collide and RLS can scope by the user's folder.
    const path = `${userId || "anon"}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/images/${path}`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${token}`,
        "Content-Type": mime,
        "x-upsert": "true",
      },
      body: blob,
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      devWarn("uploadImage storage error:", res.status, err);
      return null;
    }
    // Public URL for the object (bucket must be public-read).
    return `${SUPABASE_URL}/storage/v1/object/public/images/${path}`;
  } catch (e) {
    devWarn("uploadImage failed:", e);
    return null;
  }
}

// Group photos are private: they upload to the non-public `group-images` bucket under a
// per-group folder. A storage RLS policy only lets group members write there, so the returned
// value is the storage PATH (not a public URL) — there is no public URL for a private object.
// Viewing goes through signGroupImage() below, which mints a short-lived signed URL that the
// same membership policy gates. Net effect: only members can upload or view a group's photos.
export async function uploadGroupImage(base64DataUrl, token, groupId) {
  if (!base64DataUrl || !token || !groupId) return null;
  try {
    const compressed = await compressImage(base64DataUrl);
    const mime = compressed.match(/data:(.*?);/)?.[1] || "image/jpeg";
    const ext = mime.split("/")[1]?.split("+")[0] || "jpg";
    const base64 = compressed.split(",")[1] || "";
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    // A File (not a bare Blob) so CapacitorHttp's native bridge treats the body as a binary
    // upload and base64-encodes it — a plain Blob falls through its type check and is sent as
    // broken JSON. A File is also a valid fetch body on web, so this works in both paths.
    const blob = new File([bytes], `upload.${ext}`, { type: mime });
    // Folder = group id so the RLS policy can scope writes/reads to that group's members.
    const path = `${groupId}/${Date.now()}-${Math.random().toString(36).slice(2, 8)}.${ext}`;
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/group-images/${path}`, {
      method: "POST",
      headers: { "Authorization": `Bearer ${token}`, "Content-Type": mime, "x-upsert": "true" },
      body: blob,
    });
    if (!res.ok) {
      const err = await res.text().catch(() => "");
      devWarn("uploadGroupImage storage error:", res.status, err);
      return null;
    }
    return path; // store the private path in group_posts.image_url
  } catch (e) {
    devWarn("uploadGroupImage failed:", e);
    return null;
  }
}

// Mint a short-lived signed URL for a private group image. The storage RLS SELECT policy only
// lets members sign, so a non-member's request 403s and returns null (image just doesn't render).
export async function signGroupImage(path, token) {
  if (!path || !token) return null;
  try {
    const res = await fetch(`${SUPABASE_URL}/storage/v1/object/sign/group-images/${path}`, {
      method: "POST",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${token}`, "Content-Type": "application/json" },
      body: JSON.stringify({ expiresIn: 3600 }),
    });
    if (!res.ok) return null;
    const data = await res.json().catch(() => null);
    const signed = data?.signedURL || data?.signedUrl;
    return signed ? `${SUPABASE_URL}/storage/v1${signed}` : null;
  } catch {
    return null;
  }
}

// DELETING A POST DELETES ITS PHOTO. Nothing in this file issued a storage DELETE until now — a
// removed post's image sat in the bucket forever, public or private. Both are best-effort: the
// Postgres row is the source of truth for "does this post exist", so a failed cleanup here leaves
// an orphaned object rather than blocking or reverting the deletion the user actually asked for.
async function deletePublicImage(imageUrl, token) {
  if (!imageUrl || !token) return;
  const marker = "/storage/v1/object/public/images/";
  const i = imageUrl.indexOf(marker);
  if (i === -1) return; // not one of ours (external/legacy URL) — nothing to clean up
  const path = imageUrl.slice(i + marker.length);
  try {
    await fetch(`${SUPABASE_URL}/storage/v1/object/images/${path}`, {
      method: "DELETE",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${token}` },
    });
  } catch (e) { devWarn("deletePublicImage failed:", e); }
}
export async function deleteGroupImage(path, token) {
  if (!path || !token) return;
  try {
    await fetch(`${SUPABASE_URL}/storage/v1/object/group-images/${path}`, {
      method: "DELETE",
      headers: { "apikey": SUPABASE_KEY, "Authorization": `Bearer ${token}` },
    });
  } catch (e) { devWarn("deleteGroupImage failed:", e); }
}


// Session storage
const SESSION_STORAGE_KEY = "seshd_session";
// ── Session tokens: iOS Keychain on native, localStorage on web ─────────────────
// On a native build with capacitor-secure-storage-plugin synced, the Supabase
// access/refresh tokens live ONLY in the hardware-encrypted Keychain — never in
// localStorage or the Preferences (UserDefaults) mirror, both of which are
// unencrypted at rest. Reads stay synchronous for the ~30 call sites via a module
// cache that boot hydration populates from the Keychain BEFORE React mounts (see
// hydrateSessionFromKeychain). Web builds and native builds that haven't run
// `npx cap sync ios` yet keep the localStorage path unchanged.
function secureStore() {
  const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
  if (Cap?.isNativePlatform?.() && Cap.Plugins?.SecureStoragePlugin) return Cap.Plugins.SecureStoragePlugin;
  return null;
}
let _sessionCache; // undefined = not hydrated; null = known signed-out; object = session
export function loadSession() {
  if (_sessionCache !== undefined) return _sessionCache;
  try { return JSON.parse(localStorage.getItem(SESSION_STORAGE_KEY)); } catch { return null; }
}
// Boot/session diagnostics — surfaced as a tiny line on the auth screen so a device where
// session persistence fails can tell us exactly which step went wrong (Keychain hit/miss/error,
// save confirmed/failed). Keys start with seshd_ so the Preferences mirror carries them too.
function setBootDiag(s) { try { localStorage.setItem("seshd_boot_diag", String(s).slice(0, 80)); } catch {} }
function setSaveDiag(s) { try { localStorage.setItem("seshd_kc_save", String(s).slice(0, 60)); } catch {} }
// PARANOIA RULE for everything below: never destroy a copy of the session until its
// replacement write is CONFIRMED. A silently-failing Keychain plugin must degrade to
// "session kept in localStorage/Preferences" (still app-sandboxed), never to "signed out".
export function saveSession(s) {
  const sec = secureStore();
  const payload = JSON.stringify(s);
  if (sec) {
    _sessionCache = s;
    try {
      sec.set({ key: SESSION_STORAGE_KEY, value: payload }).then(() => {
        setSaveDiag("kc-save:ok");
        // Keychain write CONFIRMED — now it's safe to scrub the unencrypted copies
        // (explicitly on both stores, so this holds even if the mirror isn't installed).
        try { localStorage.removeItem(SESSION_STORAGE_KEY); } catch {}
        try { nativePrefs()?.remove({ key: SESSION_STORAGE_KEY }).catch(() => {}); } catch {}
      }).catch((e) => {
        setSaveDiag("kc-save:err " + String((e && e.message) || e || "?").slice(0, 32));
        try { localStorage.setItem(SESSION_STORAGE_KEY, payload); } catch {}
      });
    } catch (e) {
      setSaveDiag("kc-save:threw");
      try { localStorage.setItem(SESSION_STORAGE_KEY, payload); } catch {}
    }
  } else {
    try { localStorage.setItem(SESSION_STORAGE_KEY, payload); } catch {}
  }
}
function clearSession() {
  _sessionCache = secureStore() ? null : undefined;
  try { localStorage.removeItem(SESSION_STORAGE_KEY); } catch {}
  try { secureStore()?.remove({ key: SESSION_STORAGE_KEY }).catch(() => {}); } catch {}
  try { nativePrefs()?.remove({ key: SESSION_STORAGE_KEY }).catch(() => {}); } catch {}
}
// Resolve to undefined (instead of hanging) if a plugin call never settles — a wedged bridge
// must not white-screen the boot forever.
function _withTimeout(p, ms) {
  return Promise.race([p, new Promise(res => setTimeout(() => res(undefined), ms))]);
}
// Boot-time hydration + one-time migration. Runs inside hydrateFromNative() (before React
// mounts), so synchronous loadSession() calls see the Keychain session from the first render.
async function hydrateSessionFromKeychain() {
  const sec = secureStore();
  if (!sec) { setBootDiag("kc:no-plugin"); return; }
  try {
    const res = await _withTimeout(sec.get({ key: SESSION_STORAGE_KEY }), 4000);
    if (res === undefined) {
      // Timed out — Keychain state unknown. Fall back to any localStorage copy but do NOT
      // scrub or migrate anything (we might race a functioning-but-slow plugin).
      setBootDiag("kc:timeout");
      try { _sessionCache = JSON.parse(localStorage.getItem(SESSION_STORAGE_KEY)) || null; } catch { _sessionCache = null; }
      return;
    }
    const value = res && res.value;
    _sessionCache = value ? JSON.parse(value) : null;
    setBootDiag(value ? "kc:hit" : "kc:empty");
    // Keychain is the source of truth now — scrub any old unencrypted copies explicitly.
    try { localStorage.removeItem(SESSION_STORAGE_KEY); } catch {}
    try { await nativePrefs()?.remove({ key: SESSION_STORAGE_KEY }); } catch {}
  } catch (e) {
    // Keychain miss (first run) or a broken plugin. Use the localStorage copy if present —
    // and NEVER null a session we successfully parsed just because the migration write fails.
    let raw = null;
    try { raw = localStorage.getItem(SESSION_STORAGE_KEY); } catch {}
    if (raw) {
      try { _sessionCache = JSON.parse(raw); } catch { _sessionCache = null; raw = null; }
    } else {
      _sessionCache = null;
    }
    setBootDiag("kc:miss(" + String((e && e.message) || e || "?").slice(0, 24) + ") ls:" + (raw ? "hit" : "none"));
    if (raw && _sessionCache) {
      // Best-effort migration into the Keychain; scrub the plaintext copies ONLY on success.
      try {
        await sec.set({ key: SESSION_STORAGE_KEY, value: raw });
        localStorage.removeItem(SESSION_STORAGE_KEY);
        try { await nativePrefs()?.remove({ key: SESSION_STORAGE_KEY }); } catch {}
      } catch { /* keep the localStorage fallback — signed-in beats scrubbed */ }
    }
  }
}

// queryWithRetry moved into src/lazy/MessagesScreen.jsx (Aug 24) — it existed only for
