    // versions were already AAA and are untouched.
    orange: "#c2490a",
    green: "#047f59",           // success shifted bluer (emerald) so it never reads as the accent
    gold: "#976703",
    red: "#da1c46",
    text: "#1c1b1a",        // deep warm near-black for crisp reading
    textDim: "#3a3936",
