  // every 3 hours, and dots turn GREEN across the sleep stretch so the night reads at a glance.
  const rechargeRanges = segs.filter(s => s.phase === "recharge" && s.pts.length >= 2).map(s => [s.pts[0].ts, s.pts[s.pts.length - 1].ts]);
