const REST_NOTIF_ID = 7711; // fixed id so we can reliably cancel/replace the rest notification
let __notifPermAsked = false;
async function ensureNotifPermission() {
  const LN = nativeLocalNotifs();
  if (!LN) return false;
  try {
    const status = await LN.checkPermissions();
    if (status?.display === "granted") return true;
    if (__notifPermAsked) return false; // don't nag if already asked & denied this session
    __notifPermAsked = true;
    const req = await LN.requestPermissions();
    return req?.display === "granted";
  } catch { return false; }
}
// Schedule the "rest is up" notification `seconds` from now. Cancels any prior one first.
async function scheduleRestNotification(seconds) {
  const LN = nativeLocalNotifs();
  if (!LN || !seconds || seconds < 1) return;
  try {
    const ok = await ensureNotifPermission();
    if (!ok) return;
    await LN.cancel({ notifications: [{ id: REST_NOTIF_ID }] }).catch(() => {});
    await LN.schedule({
      notifications: [{
        id: REST_NOTIF_ID,
        title: "Rest's up — back to work",
        body: "Go hit your next set",
        schedule: { at: new Date(Date.now() + seconds * 1000) },
        sound: "default",
      }],
    });
  } catch {}
}
async function cancelRestNotification() {
  const LN = nativeLocalNotifs();
  if (!LN) return;
  try { await LN.cancel({ notifications: [{ id: REST_NOTIF_ID }] }); } catch {}
}

// ═════════════════════════════════════════════════════════════════════════════
// NETWORK STATUS — offline detection. Uses the Capacitor Network plugin for reliable
// native state + change events, falling back to navigator.onLine on web. Drives the
// "you're offline" indicator and (later) the sync-queue flush on reconnect.
// ═════════════════════════════════════════════════════════════════════════════
function nativeNetwork() {
  const Cap = (typeof window !== "undefined") ? window.Capacitor : null;
  if (Cap?.isNativePlatform?.() && Cap.Plugins?.Network) return Cap.Plugins.Network;
  return null;
}
// Subscribe to connectivity changes. Calls cb(isOnline) on every change and once initially.
// Returns an unsubscribe function. Works on web (online/offline events) and native (plugin).
function subscribeNetwork(cb) {
  const N = nativeNetwork();
  if (N) {
    let handle = null;
    try { N.getStatus().then(s => cb(!!s.connected)).catch(() => cb(true)); } catch { cb(true); }
    try { handle = N.addListener("networkStatusChange", (s) => cb(!!s.connected)); } catch {}
    return () => { try { handle?.remove?.(); } catch {} };
  }
  // Web fallback
  const on = () => cb(true), off = () => cb(false);
  try {
    cb(typeof navigator !== "undefined" ? navigator.onLine !== false : true);
    window.addEventListener("online", on);
    window.addEventListener("offline", off);
  } catch {}
  return () => { try { window.removeEventListener("online", on); window.removeEventListener("offline", off); } catch {} };
}


const SEED_GROUPS = [
  { id:"g1", name:"The Crew", description:"Our gym group — training log + accountability", createdBy:"u1", members:["u1","u2","u3","u7"], icon:"🏋️" },
  { id:"g2", name:"Pull Day Party", description:"Back & biceps obsessed", createdBy:"u3", members:["u3","u1","u2","u7"], icon:"💪" },
  { id:"g3", name:"Form Checkers", description:"Post videos, get feedback from real coaches", createdBy:"u4", members:["u4","u1","u6","u9"], icon:"🎥" },
];

// ═════════════════════════════════════════════════════════════════════════════
// STORAGE
// ═════════════════════════════════════════════════════════════════════════════
const SK = "seshd_v1";
// One-time cleanup of old localStorage keys no longer used.
// Safe to call on every load — the keys just get removed if present.
function cleanupStaleLocalStorage() {
  try {
    localStorage.removeItem("seshd_exercise_gifs_v1");
    localStorage.removeItem("seshd_exercise_gifs_v2");
    localStorage.removeItem("seshd_last_activity"); // replaced by seshd_seen_activity_count
  } catch {}
}
// One-time: drop the LOCAL T-Bar Row PR baselines so they rebuild from the corrected history.
// Mo logged every T-Bar Row with the bar's 45 lbs added on top, and the whole history was fixed at
// the source. That alone does NOT reach the phone: loadUserData rebuilds prs/prsE1rm/prsVolume from
// history and then MAX-MERGES the in-memory copy over the top (deliberately — it's what stops a
// failed PR upsert from losing a real best), and that copy is rehydrated from localStorage every
// boot, so the inflated 135 would win the max forever.
//
// This runs INSIDE loadStore, i.e. before anything reads the store — not in an effect after mount.
// The effect version was written first and pw_tbarpr caught it failing two ways: it stripped the
// key AFTER loadUserData had already rebuilt it, so the PR was simply MISSING for the rest of that
// session, and a later persist of a stale snapshot put the inflated value straight back on the next
// launch. Cleaning the persisted copy before hydration means `prev` never carries the bad number
// and the normal rebuild produces the corrected one with no special-casing anywhere else.
function migrateTbarPRs(store) {
  try { if (localStorage.getItem("seshd_tbar_pr_reset_v1")) return store; } catch { return store; }
  const isTbar = (n) => /\bt-?bar\b/i.test(n || "");
  let changed = false;
  for (const key of ["prs", "prsE1rm", "prsVolume"]) {
    const m = store[key];
    if (!m || typeof m !== "object") continue;
    for (const name of Object.keys(m)) {
      if (isTbar(name)) { delete m[name]; changed = true; }
    }
  }
  // Flag the device even when nothing matched, so this never rescans on later boots.
  try { localStorage.setItem("seshd_tbar_pr_reset_v1", "1"); } catch {}
  if (changed) { try { localStorage.setItem(SK, JSON.stringify(store)); } catch {} }
  return store;
}
